(()=>{'use strict';
const NS='http://www.w3.org/2000/svg',SAVE='crownfall-v3-save';
class RNG{constructor(seed=84217){this.s=seed>>>0}next(){this.s=(1664525*this.s+1013904223)>>>0;return this.s/4294967296}pick(a){return a[Math.floor(this.next()*a.length)]}}
const REALMS=['Veyra','Ordel','Kharad','Elaris','Mourn','Caerwyn','Ilyrion','Sablemarch'];
const COLORS=['#7b4245','#41647b','#806b3b','#4b714e','#6b4c76','#815c43','#527587','#754653'];
const FIRST=['Aldren','Mara','Edric','Lyra','Torvan','Ellyn','Maeric','Soren','Azram','Rashad','Aelwyn','Caelan','Velka','Varos','Cassian','Elara','Orren','Talia','Beren','Seris','Lucan','Nerys','Hadric','Vela'];
const HOUSES=['Veyr','Ash','Green','Ordel','Iceborn','Khar','Elar','Velka','Varos','Caer','Ilyr','Sable','Dawn','Vale'];
const TRAITS=['Ambitious','Just','Brave','Patient','Greedy','Clever','Calm','Warlike','Builder','Schemer','Loyal','Proud'];
const ROOTS=['Veyr','Green','Ashen','Dawn','Silver','Frost','Red','Sun','Elar','Thorn','Mourn','Black','Caer','West','Stone','Bright','Sable','Night','Grey','Oak','Raven','High','Iron','Star','Mist','Wolf','Gold','Moon','Rose','Ember','Crow','White','Storm','Alder','Cold','Falcon','Wyrm','Dusk','Rook','Pine'];
const ENDS=['hold','mere','ford','watch','bay','fen','vale','scar','wood','spire','tide','rest','cross','lake','keep','field','pass','fall','haven','reach'];
function generateWorld(seed=84217){const rng=new RNG(seed),characters={},titles={},provinces=[],relations={};let pc=0,tc=0;const person=(house,born)=>{const id='p'+(++pc),sex=rng.next()>.5?'F':'M';characters[id]={id,name:rng.pick(FIRST)+' '+house,house,sex,born:born??790+Math.floor(rng.next()*34),alive:true,traits:[rng.pick(TRAITS),rng.pick(TRAITS)],parents:[],children:[],spouse:null,opinions:{}};return id};const realms=REALMS.map((name,i)=>({name,color:COLORS[i],ruler:person(i===0?'Veyr':HOUSES[(i+3)%HOUSES.length],792+i*2),duchies:[]}));characters[realms[0].ruler].name='Aldren II Veyr';let used=new Set,cols=14,rows=9;const countyName=()=>{let n;do n=rng.pick(ROOTS)+rng.pick(ENDS);while(used.has(n));used.add(n);return n};const isLand=(x,y)=>{let nx=(x-(cols-1)/2)/(cols*.53),ny=(y-(rows-1)/2)/(rows*.54),d=Math.sqrt(nx*nx+ny*ny),noise=(rng.next()-.5)*.34,bite=(x<3&&y>4)||(x>10&&y<3);return d+noise<.88&&!bite};for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){let i=y*cols+x,id='c'+i,land=isLand(x,y),xx=25+x*82+(y%2)*15+(rng.next()-.5)*12,yy=25+y*78+(rng.next()-.5)*10,ri=Math.min(7,Math.floor(x/3.5)+Math.floor(y/4.5)*4),realm=realms[ri],band=Math.floor(y/3),duchy=realm.name+' '+['Heartlands','March','Reach'][Math.min(2,(x+band)%3)];if(land&&!realm.duchies.includes(duchy))realm.duchies.push(duchy);let elev=.18+.7*(1-Math.abs(x-cols/2)/(cols/2))+.18*(rng.next()-.5),moist=rng.next(),terrain=elev>.72?'highlands':elev>.58?'hills':moist>.72?'forest':moist<.18?'marsh':'plains';provinces.push({id,name:countyName(),x:xx,y:yy,land,realm:realm.name,duchy,terrain,elevation:elev,moisture:moist,dev:10+Math.floor(rng.next()*31),control:60+Math.floor(rng.next()*41),pop:2000+Math.floor(rng.next()*9000),river:false});relations[id]=[]}
provinces.forEach((p,i)=>{let x=i%cols,y=Math.floor(i/cols);[[x-1,y],[x+1,y],[x,y-1],[x,y+1],[x+(y%2?1:-1),y-1],[x+(y%2?1:-1),y+1]].forEach(([a,b])=>{if(a>=0&&a<cols&&b>=0&&b<rows){let q=provinces[b*cols+a];if(p.land&&q.land&&!relations[p.id].includes(q.id))relations[p.id].push(q.id)}})});
const rivers=[];provinces.filter(p=>p.land&&p.elevation>.65).slice(0,5).forEach(start=>{let path=[start.id],cur=start,seen=new Set(path);for(let n=0;n<8;n++){let opts=relations[cur.id].map(id=>provinces.find(p=>p.id===id)).filter(p=>!seen.has(p.id)).sort((a,b)=>a.elevation-b.elevation);if(!opts.length)break;cur=opts[0];path.push(cur.id);cur.river=true;seen.add(cur.id);if(cur.elevation<.3)break}if(path.length>2)rivers.push(path)});
realms.forEach(r=>{let kid='t'+(++tc);titles[kid]={id:kid,tier:'kingdom',name:'Kingdom of '+r.name,holderId:r.ruler,deJureLiegeId:null,currentLiegeId:null,children:[]};r.titleId=kid;r.duchies.forEach((d,di)=>{let dps=provinces.filter(p=>p.land&&p.realm===r.name&&p.duchy===d);if(!dps.length)return;let duke=di===0?r.ruler:person(rng.pick(HOUSES));let did='t'+(++tc);titles[did]={id:did,tier:'duchy',name:'Duchy of '+d,holderId:duke,deJureLiegeId:kid,currentLiegeId:kid,children:[]};titles[kid].children.push(did);dps.forEach((p,ci)=>{let holder=ci===0?duke:person(rng.pick(HOUSES)),cid='t'+(++tc);titles[cid]={id:cid,tier:'county',name:'County of '+p.name,holderId:holder,deJureLiegeId:did,currentLiegeId:did,provinceId:p.id,children:[]};titles[did].children.push(cid);p.titleId=cid})})});return{seed,provinces,relations,characters,titles,realms,rivers}}
const TIER={county:1,duchy:2,kingdom:3,empire:4};function rebuildFeudal(w){Object.values(w.characters).forEach(c=>{c.titleIds=[];c.primaryTitleId=null;c.liegeId=null;c.vassalIds=[];c.domainTax=0;c.domainLevy=0;c.vassalTax=0;c.vassalLevy=0});Object.values(w.titles).forEach(t=>{let c=w.characters[t.holderId];if(!c)return;c.titleIds.push(t.id);if(!c.primaryTitleId||TIER[t.tier]>TIER[w.titles[c.primaryTitleId].tier])c.primaryTitleId=t.id});Object.values(w.characters).forEach(c=>{if(!c.primaryTitleId)return;let t=w.titles[c.primaryTitleId],lt=t.currentLiegeId&&w.titles[t.currentLiegeId];if(lt&&lt.holderId!==c.id)c.liegeId=lt.holderId});Object.values(w.characters).forEach(c=>{if(c.liegeId&&w.characters[c.liegeId]&&!w.characters[c.liegeId].vassalIds.includes(c.id))w.characters[c.liegeId].vassalIds.push(c.id)});recalcFeudal(w)}function recalcFeudal(w){Object.values(w.characters).forEach(c=>{c.domainTax=0;c.domainLevy=0;c.vassalTax=0;c.vassalLevy=0});w.provinces.filter(p=>p.land&&p.titleId).forEach(p=>{let h=w.characters[w.titles[p.titleId].holderId];if(!h)return;h.domainTax+=(p.pop/1000)*(p.dev/20)*(p.control/100);h.domainLevy+=Math.round(p.pop*(.025+p.dev/2500)*(p.control/100))});Object.values(w.characters).forEach(v=>{if(!v.liegeId)return;let l=w.characters[v.liegeId];if(!l)return;l.vassalTax+=(v.domainTax+v.vassalTax)*.12;l.vassalLevy+=Math.round((v.domainLevy+v.vassalLevy)*.22)})}function feudalChain(w,id){let out=[],c=w.characters[id],seen=new Set;while(c&&!seen.has(c.id)){out.push(c);seen.add(c.id);c=c.liegeId?w.characters[c.liegeId]:null}return out}
let W=null,S=null,timer=null;const $=s=>document.querySelector(s),map=$('#map'),left=$('#left'),right=$('#right'),world=$('#world');let cam={x:0,y:0,z:1},drag=null;const terrainColors={plains:'#77774b',forest:'#365b3b',hills:'#806d4b',marsh:'#4c675d',highlands:'#68615b'};function newGame(){W=generateWorld(84217);rebuildFeudal(W);S={year:842,month:3,day:17,paused:true,speed:1,playerCharacterId:null,selectedProvinceId:null,mapMode:'political',history:[],treasuries:{},factions:[]};Object.keys(W.characters).forEach(id=>S.treasuries[id]=50);$('#startScreen').classList.add('hidden');render();saveGame()}function saveGame(){if(!W||!S)return;localStorage.setItem(SAVE,JSON.stringify({W,S}))}function loadGame(){try{let d=JSON.parse(localStorage.getItem(SAVE));if(!d)throw 0;W=d.W;S=d.S;rebuildFeudal(W);$('#startScreen').classList.add('hidden');render()}catch(e){newGame()}}function hasSave(){return !!localStorage.getItem(SAVE)}
function node(tag,attrs={}){let n=document.createElementNS(NS,tag);Object.entries(attrs).forEach(([k,v])=>n.setAttribute(k,v));return n}function poly(p){let x=p.x,y=p.y,j=(+p.id.slice(1)%5)-2;return`${x-4},${y+15} ${x+34+j*2},${y-3} ${x+76},${y+9+j} ${x+88},${y+50} ${x+62},${y+78} ${x+18},${y+72} ${x-8},${y+45}`}function fill(p){if(S.mapMode==='terrain')return terrainColors[p.terrain];if(S.mapMode==='dejure'){let ds=[...new Set(W.provinces.filter(x=>x.land).map(x=>x.duchy))],i=ds.indexOf(p.duchy);return`hsl(${i*29%360} 32% 42%)`}return W.realms.find(r=>r.name===p.realm)?.color||'#666'}
function draw(){if(!W)return;map.innerHTML='';let g=node('g',{transform:`translate(${cam.x} ${cam.y}) scale(${cam.z})`});map.append(g);W.provinces.forEach(p=>{if(!p.land)return;let q=node('polygon',{points:poly(p),fill:fill(p),class:'province '+(S.selectedProvinceId===p.id?'selected':'')});q.onclick=()=>{S.selectedProvinceId=p.id;render();if(matchMedia('(max-width:900px)').matches){right.classList.add('open');left.classList.remove('open')}};g.append(q);let mark=node('text',{x:p.x+40,y:p.y+61,class:'settlementMark'});mark.textContent=p.dev>32?'♜':p.dev>22?'♖':'⌂';g.append(mark);let t=node('text',{x:p.x+39,y:p.y+43,class:'label'});t.textContent=p.name;g.append(t)});W.rivers.forEach(path=>{let pts=path.map(id=>{let p=W.provinces.find(x=>x.id===id);return`${p.x+40},${p.y+40}`}).join(' ');g.append(node('polyline',{points:pts,class:'river'}))});if(S.mapMode==='political')W.realms.forEach(r=>{let ps=W.provinces.filter(p=>p.land&&p.realm===r.name);if(!ps.length)return;let t=node('text',{x:ps.reduce((s,p)=>s+p.x,0)/ps.length+35,y:ps.reduce((s,p)=>s+p.y,0)/ps.length+35,class:'realmLabel'});t.textContent=r.name.toUpperCase();g.append(t)})}
const age=c=>S.year-c.born,rank=c=>c.primaryTitleId?W.titles[c.primaryTitleId].tier:'unlanded';function charCard(c){return`<div class="card"><div class="portraitFallback">${c.sex==='F'?'♛':'♚'}</div><b>${c.name}</b><div class="muted">House ${c.house} · Age ${age(c)} · ${rank(c)}</div><div>${c.traits.map(t=>`<span class="trait">${t}</span>`).join('')}</div></div>`}
function renderLeft(){if(!S.playerCharacterId){left.innerHTML='<h2>Choose a Ruler</h2><div class="muted">Observer mode. Pick a sovereign to begin.</div>'+W.realms.map(r=>{let c=W.characters[r.ruler];return`<div class="title rulerPick" data-play="${c.id}"><b>${r.name}</b><div class="muted">${c.name}</div></div>`}).join('');left.querySelectorAll('[data-play]').forEach(e=>e.onclick=()=>{S.playerCharacterId=e.dataset.play;S.history.unshift(`${S.year}.03 — You now play as ${W.characters[e.dataset.play].name}.`);left.classList.remove('open');render();saveGame()});return}let c=W.characters[S.playerCharacterId],held=c.titleIds.map(id=>W.titles[id]),liege=c.liegeId&&W.characters[c.liegeId];left.innerHTML=`${charCard(c)}<div class="card"><div class="row"><span>Treasury</span><b>${Math.floor(S.treasuries[c.id]||0)}g</b></div><div class="row"><span>Domain tax</span><b>${c.domainTax.toFixed(1)}</b></div><div class="row"><span>Total levy</span><b>${c.domainLevy+c.vassalLevy}</b></div></div>${liege?`<h3>Liege</h3><div class="title">${liege.name}</div>`:''}<h3>Vassals (${c.vassalIds.length})</h3>${c.vassalIds.slice(0,10).map(id=>`<div class="title">${W.characters[id].name}</div>`).join('')||'<div class="muted">No direct vassals.</div>'}<h3>Titles</h3>${held.map(t=>`<div class="title">${t.name}<div class="muted">${t.tier}</div></div>`).join('')}<h3>Chronicle</h3>${S.history.map(h=>`<div class="title muted">${h}</div>`).join('')}`}
function renderRight(){let p=W.provinces.find(x=>x.id===S.selectedProvinceId);if(!p){right.innerHTML='<h2>World</h2><div class="muted">Drag to pan. Tap a county to inspect it.</div>';return}let t=W.titles[p.titleId],c=W.characters[t.holderId],chain=feudalChain(W,c.id);right.innerHTML=`<h2>${p.name}</h2><div class="muted">${p.terrain} · ${p.realm}${p.river?' · river':''}</div><div class="card"><div class="row"><span>Development</span><b>${p.dev}</b></div><div class="row"><span>Control</span><b>${p.control}%</b></div><div class="row"><span>Population</span><b>${p.pop.toLocaleString()}</b></div></div>${charCard(c)}<h3>${t.name}</h3><h3>Feudal Chain</h3>${chain.map(x=>`<div class="title"><b>${x.name}</b><div class="muted">${W.titles[x.primaryTitleId]?.name||'Unlanded'}</div></div>`).join('')}<button id="playHere">Play ${c.name.split(' ')[0]}</button>`;$('#playHere').onclick=()=>{S.playerCharacterId=c.id;right.classList.remove('open');render();saveGame()}}
function render(){if(!W)return;$('#date').textContent=`${S.day}/${S.month}/${S.year}`;$('#status').textContent=S.playerCharacterId?`Playing: ${W.characters[S.playerCharacterId].name}`:'Observer Mode';$('#pause').textContent=S.paused?'▶':'⏸';draw();renderLeft();renderRight();document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===S.mapMode))}
function tick(){if(!W||S.paused)return;for(let i=0;i<S.speed;i++){S.day+=3;if(S.day>28){S.day-=28;S.month++;if(S.month>12){S.month=1;S.year++}}}render();saveGame()}
$('#newGame').onclick=newGame;$('#continueGame').onclick=loadGame;$('#continueGame').disabled=!hasSave();$('#wipeSave').onclick=()=>{localStorage.removeItem(SAVE);$('#continueGame').disabled=true};document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{if(!S)return;S.mapMode=b.dataset.mode;render()});document.querySelectorAll('[data-speed]').forEach(b=>b.onclick=()=>{if(!S)return;S.speed=+b.dataset.speed;S.paused=false;render()});$('#pause').onclick=()=>{if(!S)return;S.paused=!S.paused;render()};$('#leftToggle').onclick=()=>{left.classList.toggle('open');right.classList.remove('open')};$('#rightToggle').onclick=()=>{right.classList.toggle('open');left.classList.remove('open')};world.onwheel=e=>{if(!W)return;e.preventDefault();cam.z=Math.max(.55,Math.min(2.6,cam.z*(e.deltaY<0?1.12:.89)));draw()};world.onpointerdown=e=>{if(!W)return;drag={x:e.clientX,y:e.clientY,cx:cam.x,cy:cam.y};world.setPointerCapture?.(e.pointerId)};world.onpointermove=e=>{if(!drag)return;cam.x=drag.cx+e.clientX-drag.x;cam.y=drag.cy+e.clientY-drag.y;draw()};world.onpointerup=world.onpointercancel=()=>drag=null;timer=setInterval(tick,800);window.addEventListener('error',e=>{let d=$('#debug');if(d){d.textContent='Runtime error: '+e.message;d.hidden=false}});})();